def has_vertical_continuity(row_data, row_idx, color):
    """Check if row_idx-1, row_idx, row_idx+1 all have the same color at each column position."""
    curr_row = row_data[row_idx]
    for col in range(len(curr_row)):
        if row_idx - 1 >= 0 and row_data[row_idx - 1][col] != color:
            return False
        if row_idx + 1 < len(row_data) and row_data[row_idx + 1][col] != color:
            return False
    return True

def transform(grid):
    """Transform grid based on the pattern: in mixed rows, cells with vertical continuity become 1."""
    result = [row[:] for row in grid]  # Deep copy
    for r in range(len(grid)):
        if len(set(grid[r])) > 1:  # Mixed row
            for c in range(len(grid[r])):
                val = grid[r][c]
                if has_vertical_continuity(grid, r, val):
                    result[r][c] = 1
    return result

